# Hand-written; kept out of codegen (_SKIP) because packagedata arrays require
# a row-per-record table format that the autogenerated separate-array approach
# does not produce. Specify packagedata as a list of tuples:
#   [(iviscspec, dviscdc, cviscref, modelname, auxspeciesname), ...]
from pathlib import Path
from typing import Optional

from xattree import xattree

from flopy4.mf6.package import Package
from flopy4.mf6.spec import field, path
from flopy4.utils import to_path


@xattree(kw_only=True)
class Vsc(Package):
    viscref: Optional[float] = field(block="options", default=None, longname="reference viscosity")
    temperature_species_name: Optional[str] = field(
        block="options", default=None, longname="auxspeciesname that corresponds to temperature"
    )
    thermal_formulation: Optional[str] = field(
        block="options",
        default=None,
        longname="keyword to specify viscosity formulation for the temperature species",
    )
    thermal_a2: Optional[float] = field(
        block="options", default=None, longname="coefficient used in nonlinear viscosity function"
    )
    thermal_a3: Optional[float] = field(
        block="options", default=None, longname="coefficient used in nonlinear viscosity function"
    )
    thermal_a4: Optional[float] = field(
        block="options", default=None, longname="coefficient used in nonlinear viscosity function"
    )
    viscosity_filerecord: Optional[Path] = path(
        block="options", default=None, converter=to_path, inout="fileout"
    )
    nviscspecies: int = field(
        block="dimensions",
        default=0,
        longname="number of species used in viscosity equation of state",
    )
    # Each row: (iviscspec, dviscdc, cviscref, modelname, auxspeciesname)
    # TODO: replace with named column fields (iviscspec, dviscdc, cviscref, modelname,
    # auxspeciesname) once the unstructure layer combines packagedata-block arrays
    # into an xr.Dataset the way period data is combined, so they write as a
    # row-per-record table instead of separate named arrays.
    packagedata: Optional[list] = field(block="packagedata", default=None)
